static void ck(cudaError_t s){if(s!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(s));}
template<typename T>std::vector<T>load(std::string f,int n){std::ifstream s(f,std::ios::binary);std::vector<T>x(n);s.read((char*)x.data(),n*sizeof(T));if(!s||s.peek()!=EOF)throw std::runtime_error("fixturebytes "+f);return x;}
template<typename T>std::vector<T>pad(const std::vector<T>&x,T g){std::vector<T>v(x.size()+32,g);std::copy(x.begin(),x.end(),v.begin()+16);return v;}
template<typename T>void cat(std::vector<double>&v,const std::vector<T>&x){for(auto a:x)v.push_back(double(a));}
template<typename T>std::vector<T>host(T*p,int n){std::vector<T>x(n);ck(cudaMemcpy(x.data(),p,n*sizeof(T),cudaMemcpyDeviceToHost));return x;}
template<typename T>T*device(const std::vector<T>&x){T*p;ck(cudaMalloc(&p,x.size()*sizeof(T)));ck(cudaMemcpy(p,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));return p;}
template<typename T>bool guards(const std::vector<T>&x,T g){return std::all_of(x.begin(),x.begin()+16,[=](T v){return v==g;})&&std::all_of(x.end()-16,x.end(),[=](T v){return v==g;});}
static hypre_Vector* hv(double*p){auto v=hypre_SeqVectorCreate(N);hypre_VectorData(v)=p;hypre_VectorOwnsData(v)=0;hypre_SeqVectorInitialize(v);return v;}
__global__ void observe_params(int*p){p[0]=N;p[1]=NX;p[2]=NY;p[3]=NZ;p[4]=R;}
struct Metrics{bool finite=true,range=true;double unweighted=0,weighted=0,residual=0;};
static Metrics metrics(const std::vector<double>&u,const std::vector<double>&w){Metrics z;for(int i=0;i<N;i++){double a=u[i+16];z.finite&=std::isfinite(a);z.range&=a>=0&&a<=2;z.unweighted=std::max(z.unweighted,fabs(a-1));z.weighted=std::max(z.weighted,fabs(a-1)/w[i]);int x=i%NX,y=(i/NX)%NY,k=i/(NX*NY),deg=0;double neighbors=0;if(k){neighbors+=u[i-NX*NY+16];deg++;}if(y){neighbors+=u[i-NX+16];deg++;}if(x){neighbors+=u[i-1+16];deg++;}if(x+1<NX){neighbors+=u[i+1+16];deg++;}if(y+1<NY){neighbors+=u[i+NX+16];deg++;}if(k+1<NZ){neighbors+=u[i+NX*NY+16];deg++;}z.residual=std::max(z.residual,fabs(6*a-neighbors-(6-deg))/w[i]);}return z;}
