auto dump=[&](const std::vector<double>&u,const std::string&name){auto path=(rawdir/(name+"_pid"+std::to_string(getpid())+".bin")).string();std::ofstream s(path,std::ios::binary);s.write((char*)u.data(),u.size()*8);if(!s)throw std::runtime_error("rawcapturewrite");return path;};
