for(int trial=1;trial<=5;trial++){std::fill(my.begin()+16,my.end()-16,0);std::copy(ay0.begin(),ay0.end(),ay.begin());ck(cudaMemcpy(du,u0.data(),u0.size()*8,cudaMemcpyHostToDevice));observe_params<<<1,1>>>(params);ck(cudaDeviceSynchronize());std::vector<double>pre;pre.reserve(COUNT);cat(pre,std::vector<double>{NX,NY,NZ,N,E,R,.5,QBOUND,WMIN,M0UPPER,ROUND_BUDGET,WEIGHTED_BOUND,EVAL_MARGIN});cat(pre,host(params,5));cat(pre,I);cat(pre,J);cat(pre,V);auto ib=host(di,N+33),jb=host(dj,E+32);auto vb=host(dv,E+32),fb=host(df,N+32),ub=host(du,N+32);cat(pre,ib);cat(pre,jb);cat(pre,vb);cat(pre,fb);cat(pre,ub);cat(pre,mx);cat(pre,ax);cat(pre,my);cat(pre,ay);cat(pre,w);
