g,%.17g,%.17g],\"relax_weighted_error\":%.17g,\"relax_weighted_bound\":%.17g,\"relax_residual_weighted_max\":%.17g,\"relax_residual_weighted_bound\":%.17g,\"raw_values_checked\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"raw_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%d},\"equilibrium_artifact\":{\"path\":\"%s\",\"count\":%d}}\n",trial,mt+gt+at,ok?"true":"false",pre.size(),cpu?"0":"null",mt,gt,at,z.weighted,WEIGHTED_BOUND,z.residual,RESID_BOUND,N,out.c_str(),pre.size(),rp.c_str(),N+32,eqpath.c_str(),N+32);fflush(stdout);if(!ok)return 4;}
